// Step 1: Validate Incident Payload
const payload = $input.first().json.body || $input.first().json;
const incident = payload.incident || payload;

if (!incident || !incident.id || !incident.code) {
  throw new Error('Invalid incident intake payload: missing incident id or code.');
}

return [{
  json: {
    isValid: true,
    validatedAt: new Date().toISOString(),
    incident: {
      id: incident.id,
      code: incident.code,
      title: incident.title || 'Unclassified Disaster Event',
      severity: incident.severity || 'CRITICAL',
      status: incident.status || 'REPORTED',
      primaryLocation: incident.primaryLocation || { name: 'Sector Alpha', coordinates: [13.01, 80.23] },
      metrics: incident.metrics || {}
    },
    responsePlan: payload.responsePlan || null,
    resources: payload.resources || null,
    simulationMode: payload.simulationMode !== undefined ? payload.simulationMode : true
  }
}];

// Step 2: Create / Update Incident in Workflow Context
const data = $input.first().json;
const incident = data.incident;

// Normalize and record incident snapshot
const normalizedRecord = {
  incidentId: incident.id,
  code: incident.code,
  intakeTimestamp: new Date().toISOString(),
  severity: incident.severity,
  waterLevel: incident.metrics?.waterLevelMeters || 0,
  affectedPopulation: incident.metrics?.affectedPopulationEstimated || 0,
  status: 'REGISTERED_IN_WORKFLOW_ORCHESTRATOR'
};

return [{
  json: {
    ...data,
    normalizedRecord,
    workflowStage: 'INCIDENT_INTAKE_COMPLETED'
  }
}];

// Step 3: Analyze Severity
const data = $input.first().json;
const severity = (data.incident?.severity || 'MEDIUM').toUpperCase();

const isCritical = severity === 'CRITICAL' || severity === 'CATASTROPHIC' || severity === 'HIGH';

return [{
  json: {
    ...data,
    analysis: {
      severity,
      isCritical,
      requiresImmediateEocApproval: isCritical,
      recommendedAction: isCritical ? 'ESCALATE_TO_CRITICAL_RESPONSE' : 'ROUTE_TO_STANDARD_MONITORING'
    }
  }
}];
